            partsUsed = "ریزوم زردرنگ بخش سنتی مورد استفاده است. مقدار بربرین و سایر مواد به گونه، محل کشت، برداشت و استخراج وابسته است. پودر ریزوم و مکمل بربرین خالص یکسان نیستند و نام گیاه روی بسته تضمین کیفیت یا خلوص محسوب نمی‌شود.",
            preparation = "در سنت‌های گیاهی از ریزوم خشک‌شده در جوشانده یا ترکیبات چندگیاهی استفاده شده است. این شرح سابقه مصرف است، نه دستور دوز. با توجه به احتمال تداخل و نبود شواهد کافی برای بسیاری از ادعاها، از تهیه عصاره غلیظ خانگی و مصرف خودسرانه پرهیز کنید.",
            specialPopulations = "بارداری، شیردهی و نوزادی از موقعیت‌هایی هستند که مصرف بربرین یا فرآورده‌های حاوی آن بدون راهنمایی تخصصی مناسب نیست. افراد مصرف‌کننده داروهای مزمن باید قبل از شروع مکمل بررسی تداخل انجام دهند. اگر علائم افت قند، تپش قلب یا عارضه شدید رخ داد، کمک پزشکی بگیرید.",
            faq = "آیا کوپتیس دیابت را درمان می‌کند؟ خیر، چنین ادعایی برای خوددرمانی قابل اتکا نیست. آیا بربرین و ریزوم کوپتیس یکی‌اند؟ خیر، فرآورده‌ها متفاوت‌اند. آیا مکمل گیاهی با دارو تداخل ندارد؟ ممکن است تداخل مهم داشته باشد و باید بررسی شود.",
            bibliography = "مرور تداخل‌های بربرین و داروها در PMC: https://pmc.ncbi.nlm.nih.gov/articles/PMC13516377/ ؛ مرور موارد تداخل بالینی با مکمل‌های سازگارپنداشته‌شده در PMC: https://pmc.ncbi.nlm.nih.gov/articles/PMC10565488/ ؛ Kew POWO: https://powo.science.kew.org/results?q=Coptis%20chinensis. به‌دلیل تغییر سریع ادبیات، منبع‌های تداخل باید در بازبینی‌های بعدی نیز دوباره بررسی شوند.",
            sourceUrl = "https://powo.science.kew.org/results?q=Coptis%20chinensis"
        )
    )

    fun apply(plant: Plant): Plant {
        val article = articles[plant.id] ?: return plant
        return plant.copy(
            description = article.description,
            habitat = article.habitat,
            care = article.care,
            traditionalUses = article.traditionalUses,
            evidence = article.evidence,
            cautions = article.cautions,
            interactions = article.interactions,
            partsUsed = article.partsUsed,
            preparation = article.preparation,
            specialPopulations = article.specialPopulations,
            faq = article.faq,
            bibliography = article.bibliography,
            sourceUrl = article.sourceUrl
        )
    }

    fun coveredSpecies(): Set<String> = articles.keys
}
